// Modern try-with-resources (Java 7+)
public List<String> readConfigFile(String path) throws IOException {
    try (var reader = Files.newBufferedReader(Path.of(path))) {
        return reader.lines().toList();
    } // reader.close() called automatically, even on exception
}

// Old pattern (Java 6) - verbose and error-prone
public List<String> readConfigFileOldWay(String path) throws IOException {
    BufferedReader reader = null;
    try {
        reader = Files.newBufferedReader(Path.of(path));
        return reader.lines().toList();
    } finally {
        if (reader != null) {
            reader.close(); // if this throws, original exception is lost!
        }
    }
}

public class DatabaseConnection implements AutoCloseable {
    private final Connection jdbcConnection;
    private final LocalDateTime openedAt;

    public DatabaseConnection(String url) throws SQLException {
        this.jdbcConnection = DriverManager.getConnection(url);
        this.openedAt = LocalDateTime.now();
        System.out.println("Connection opened at " + openedAt);
    }

    public void executeQuery(String sql) throws SQLException {
        try (var stmt = jdbcConnection.createStatement()) {
            stmt.execute(sql);
        }
    }

    @Override
    public void close() throws Exception { // AutoCloseable throws Exception
        System.out.println("Closing connection after " + 
            Duration.between(openedAt, LocalDateTime.now()).getSeconds() + "s");
        jdbcConnection.close(); // delegates to JDBC close()
    }
}

public void transferData(String sourceFile, String destUrl) throws Exception {
    // Declare multiple resources — closed in reverse order
    try (var fileReader = Files.newBufferedReader(Path.of(sourceFile));
         var httpClient = HttpClient.newHttpClient();
         var outputStream = new ByteArrayOutputStream()) {

        // Read from file
        String content = fileReader.lines()
            .collect(Collectors.joining("\n"));

        // Write to in-memory stream
        outputStream.write(content.getBytes(StandardCharsets.UTF_8));

        // Send over HTTP
        var request = HttpRequest.newBuilder()
            .uri(URI.create(destUrl))
            .POST(HttpRequest.BodyPublishers.ofByteArray(outputStream.toByteArray()))
            .build();
        httpClient.send(request, HttpResponse.BodyHandlers.ofString());

    } // Closes: outputStream, then httpClient, then fileReader
}

public class FailingResource implements AutoCloseable {
    private final String name;

    public FailingResource(String name) { this.name = name; }

    public void doWork() {
        throw new RuntimeException("Primary exception from " + name);
    }

    @Override
    public void close() {
        throw new RuntimeException("Close exception from " + name);
    }
}

public void demonstrateSuppressed() {
    try {
        try (var resource = new FailingResource("FileHandler")) {
            resource.doWork(); // throws primary exception
        } // close() throws, but is suppressed
    } catch (Exception e) {
        System.out.println("Primary: " + e.getMessage());
        for (Throwable suppressed : e.getSuppressed()) {
            System.out.println("Suppressed: " + suppressed.getMessage());
        }
    }
}

// No catch block — exception propagates to caller
public String readFileContent(String path) throws IOException {
    try (var reader = Files.newBufferedReader(Path.of(path))) {
        return reader.lines().collect(Collectors.joining("\n"));
    } // reader closes even if exception thrown, then exception propagates
}

// Service layer catches and handles
@Service
public class FileService {
    public Optional<String> loadConfig(String path) {
        try {
            return Optional.of(readFileContent(path));
        } catch (IOException e) {
            log.error("Failed to load config from {}", path, e);
            return Optional.empty(); // business logic: return empty on failure
        }
    }
}

@Repository
public class OrderRepository {
    private final DataSource dataSource;

    public List<Order> findOrdersByCustomer(Long customerId) throws SQLException {
        var orders = new ArrayList<Order>();
        var sql = "SELECT id, item, amount FROM orders WHERE customer_id = ?";

        // Nested try-with-resources: Connection -> PreparedStatement -> ResultSet
        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement(sql)) {

            stmt.setLong(1, customerId);

            try (var rs = stmt.executeQuery()) {
                while (rs.next()) {
                    orders.add(new Order(
                        rs.getLong("id"),
                        rs.getString("item"),
                        rs.getBigDecimal("amount")
                    ));
                }
            } // rs closes first
        } // then stmt, then conn returns to pool
        return orders;
    }
}
